"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[73765],{3833:e=>{e.exports=JSON.parse('{"id":"2026-07-03-api-versioning-header-guidance-corrected","date":"2026-07-03","products":["Administration"],"product":"Administration","channel":"","changeType":"Fixed","title":"API versioning header guidance corrected","excerpt":"We have corrected the API versioning guidance for the Administration API Suite to make clear which header carries the version on which kind of request.","hasArticle":true,"bodyHtml":"<p>We have corrected the <strong>API versioning</strong> guidance for the Administration API Suite to make clear which header carries the version on which kind of request.</p>\\n<p>The version is specified in the <code>Content-Type</code> header on requests that send a payload (such as <code>POST</code> and <code>PUT</code>), and in the <code>Accept</code> header on requests that return a payload (such as <code>GET</code>). Endpoints that have neither a request nor a response payload \u2014 for example a synchronous <code>DELETE</code> that returns no content \u2014 are not versioned.</p>\\n<p>The media type itself is unchanged: it still follows the pattern <code>application/vnd.{resource}.v{major}+json</code>, using major version numbers only.</p>\\n<ul>\\n<li><a href=\\"/administration/docs/suite-common#api-versioning\\">API Versioning \u2014 Administration API Essentials</a></li>\\n</ul>\\n"}')}}]);